  ('upcoming-ufc-336', 'upcoming', '2027-01-30', '{"iso":"2027-01-30","name":"UFC 336","location":"Scotiabank Arena, Toronto, Canada","main":{"fr":"Carlos Prates vs. Michael Morales — titre intérimaire des poids welters","en":"Carlos Prates vs. Michael Morales — interim welterweight title","es":"Carlos Prates vs. Michael Morales — título interino del peso wélter"},"note":{"fr":"Joshua Van défendra aussi son titre des poids mouches face à Manel Kape. Islam Makhachev, indisponible avant mi-2027, devrait affronter le vainqueur de Prates vs. Morales.","en":"Joshua Van will also defend his flyweight title against Manel Kape. Islam Makhachev, out until mid-2027, is expected to face the winner of Prates vs. Morales.","es":"Joshua Van también defenderá su título del peso mosca ante Manel Kape. Islam Makhachev, baja hasta mediados de 2027, debería enfrentarse al ganador del Prates vs. Morales."},"card":[{"a":"Carlos Prates","b":"Michael Morales","cat":"Poids welter","belt":{"fr":"Titre intérimaire","en":"Interim title","es":"Título interino"}},{"a":"Joshua Van","b":"Manel Kape","cat":"Poids mouche","belt":{"fr":"Titre","en":"Title","es":"Título"}}],"fighters":["Carlos Prates","Michael Morales"],"highlight":true}'::jsonb),
