  ('recap-ufc-332-silva-vs-wang', 'recap', '2026-10-03', '{"iso":"2026-10-03","name":"UFC 332 : Silva vs. Wang","location":"Delta Center, Salt Lake City","results":[{"fight":"Natália Silva def. Wang Cong","method":"Décision unanime","note":{"fr":"Main event · titre vacant des poids mouches féminins (48-47, 48-47, 49-46)","en":"Main event · vacant women''s flyweight title (48-47, 48-47, 49-46)","es":"Main event · título vacante del peso mosca femenino (48-47, 48-47, 49-46)"}},{"fight":"Payton Talbott def. Deiveson Figueiredo","method":"TKO","note":"Co-main event · R1, 2:09"},{"fight":"Esteban Ribovics def. King Green","method":"TKO","note":"R1, 4:08"},{"fight":"Roman Kopylov def. Ateba Gautier","method":"TKO","note":"R1, 3:12"}],"note":{"fr":"Natália Silva devient championne après le retrait sur blessure de Valentina Shevchenko. Soirée record : 11 KO/TKO sur la carte, du jamais vu à l''UFC.","en":"Natália Silva becomes champion after Valentina Shevchenko withdrew injured. A record night: 11 KO/TKOs on the card, a first in UFC history.","es":"Natália Silva se convierte en campeona tras la baja por lesión de Valentina Shevchenko. Noche récord: 11 KO/TKO en la cartelera, algo nunca visto en la UFC."}}'::jsonb),
