  ('recap-ufc-fight-night-ankalaev-vs-guskov', 'recap', '2026-07-25', '{"iso":"2026-07-25","name":"UFC Fight Night : Ankalaev vs. Guskov","location":"Etihad Arena, Abu Dhabi","results":[{"fight":"Magomed Ankalaev def. Bogdan Guskov","method":"TKO","note":"Main event · R5, 2:41"},{"fight":"Ramazan Temirov def. Steve Erceg","method":"KO","note":"Co-main event · R1, 4:21"},{"fight":"Valter Walker def. Thomas Petersen","method":"Soumission","note":"R1, 1:32 — calf slicer"},{"fight":"Muhammad Saidov def. Dustin Jacoby","method":"TKO","note":"R2, 4:49"}],"note":{"fr":"Main event jugé très terne par la critique (4 rounds peu actifs avant la finition) — Ankalaev en a depuis rejeté la responsabilité sur le manque d''engagement de Guskov.","en":"Critics found the main event very dull (4 inactive rounds before the finish) — Ankalaev has since blamed Guskov''s lack of engagement.","es":"La crítica consideró muy gris el main event (4 asaltos poco activos antes del final) — Ankalaev culpó después a la falta de iniciativa de Guskov."},"tweetUrl":"https://x.com/ufc/status/2081091312640766023"}'::jsonb),
