  ('reaction-2026-07-19-kelvin-gastelum', 'reaction', '2026-07-19', '{"iso":"2026-07-19","author":"Kelvin Gastelum","handle":"@KelvinGastelum","text":"\"I got USMAN by tko in the 3rd rd.\"","context":{"fr":"Pronostic lancé avant le combat principal — qui ne s''est pas réalisé.","en":"A prediction made before the main event — it didn''t come true.","es":"Pronóstico lanzado antes del combate estelar — que no se cumplió."}}'::jsonb),
  ('reaction-2026-07-19-communaute-mma', 'reaction', '2026-07-19', '{"iso":"2026-07-19","author":{"fr":"Communauté MMA","en":"MMA community","es":"Comunidad MMA"},"handle":null,"text":null,"summary":{"fr":"De nombreux fans et combattants ont salué la démonstration de Du Plessis, certains y voyant déjà un argument pour un troisième affrontement face au champion Sean Strickland, qu''il a déjà battu deux fois.","en":"Many fans and fighters praised Du Plessis''s performance, some already seeing it as a case for a third fight with champion Sean Strickland, whom he has beaten twice.","es":"Muchos aficionados y luchadores elogiaron la actuación de Du Plessis; algunos ya la ven como un argumento para un tercer combate ante el campeón Sean Strickland, a quien ya ha vencido dos veces."}}'::jsonb),
  ('reaction-2026-07-27-dan-hooker', 'reaction', '2026-07-27', '{"iso":"2026-07-27","author":"Dan Hooker","handle":"@thehangmanmma","text":null,"summary":{"fr":"Hooker affirme avoir reçu une vague de menaces de mort de la part de fans de Parnasse depuis l''annonce du combat, qu''il juge disproportionnée par rapport à ce qu''il avait connu face à d''autres adversaires français. Il assume pleinement son rôle de trouble-fête pour cette affiche, expliquant vouloir gâcher les débuts UFC très attendus de Parnasse devant son public.","en":"Hooker says he has received a wave of death threats from Parnasse fans since the fight was announced, far more than he had seen against other French opponents. He fully embraces his role as the spoiler, saying he wants to ruin Parnasse''s much-awaited UFC debut in front of his home crowd.","es":"Hooker afirma haber recibido una ola de amenazas de muerte de aficionados de Parnasse desde el anuncio del combate, desproporcionada respecto a lo que vivió ante otros rivales franceses. Asume plenamente su papel de aguafiestas y quiere arruinar el esperado debut de Parnasse en la UFC ante su público."},"context":{"fr":"Interview accordée à Submission Radio, à l''approche de leur combat du 5 septembre à l''UFC Paris.","en":"Interview with Submission Radio ahead of their September 5 fight at UFC Paris.","es":"Entrevista concedida a Submission Radio antes de su combate del 5 de septiembre en UFC París."}}'::jsonb),
  ('tweet-2111237953712541748', 'tweet', '2026-10-16', '{"iso":"2026-10-16","author":"UFC","handle":"@ufc","context":{"fr":"Dernier face-à-face entre Joaquin Buckley et Mike Malott, la veille du main event d''Edmonton.","en":"The final face-off between Joaquin Buckley and Mike Malott, the day before the Edmonton main event.","es":"Último cara a cara entre Joaquin Buckley y Mike Malott, la víspera del main event de Edmonton."},"url":"https://x.com/ufc/status/2111237953712541748"}'::jsonb),
  ('tweet-2104027684607254868', 'tweet', '2026-09-27', '{"iso":"2026-09-27","author":"RMC Sport Combat","handle":"@RMCSportCombat","context":{"fr":"La décision Ailín Pérez – Norma Dumont qui a laissé les consultants de RMC sans voix.","en":"The Ailín Pérez – Norma Dumont decision that left RMC''s pundits speechless.","es":"La decisión Ailín Pérez – Norma Dumont que dejó sin palabras a los comentaristas de RMC."},"url":"https://x.com/RMCSportCombat/status/2104027684607254868"}'::jsonb),
  ('tweet-2094773226719060141', 'tweet', '2026-09-01', '{"iso":"2026-09-01","author":"RMC Sport Combat","handle":"@RMCSportCombat","context":{"fr":"Premier face-à-face entre Dan Hooker et Salahdine Parnasse avant l''UFC Paris.","en":"The first face-off between Dan Hooker and Salahdine Parnasse ahead of UFC Paris.","es":"Primer cara a cara entre Dan Hooker y Salahdine Parnasse antes de UFC París."},"url":"https://x.com/RMCSportCombat/status/2094773226719060141"}'::jsonb),
  ('trash_talk-khamzat-chimaev-sean-strickland', 'trash_talk', null, '{"a":"Khamzat Chimaev","b":"Sean Strickland","date":{"fr":"Avant UFC 312","en":"Before UFC 312","es":"Antes de UFC 312"},"summary":{"fr":"Chimaev a publiquement accusé Strickland d''\"avoir peur\" de lui, en réponse à des propos jugés méprisants de l''Américain à son sujet. Strickland avait qualifié la réaction d''un autre combattant de \"lâche\" sur le même sujet.","en":"Chimaev publicly accused Strickland of being \"scared\" of him, in response to remarks from the American he found disrespectful. Strickland had called another fighter''s reaction on the same topic \"cowardly\".","es":"Chimaev acusó públicamente a Strickland de \"tenerle miedo\", en respuesta a comentarios despectivos del estadounidense sobre él. Strickland había calificado de \"cobarde\" la reacción de otro luchador sobre el mismo tema."}}'::jsonb),
  ('trash_talk-islam-makhachev-justin-gaethje', 'trash_talk', null, '{"a":"Islam Makhachev","b":"Justin Gaethje","date":{"fr":"Sur X","en":"On X","es":"En X"},"summary":{"fr":"Gaethje avait publiquement défié Makhachev à coups de pied à la tête, comparant leurs styles. Le champion avait répondu avec calme qu''il savait faire \"bien plus que donner des coups de pied\", tout en conseillant à Gaethje de rester prudent.","en":"Gaethje had publicly challenged Makhachev with talk of head kicks, comparing their styles. The champion calmly replied that he could do \"much more than kick\", while advising Gaethje to be careful.","es":"Gaethje había desafiado públicamente a Makhachev hablando de patadas a la cabeza y comparando sus estilos. El campeón respondió con calma que sabía hacer \"mucho más que dar patadas\" y le aconsejó prudencia."}}'::jsonb)
